try {
  let lim = 15;
  if (typeof limit !== 'undefined' && limit) lim = parseInt(limit);
  else if (typeof query !== 'undefined' && query && !isNaN(parseInt(query))) lim = parseInt(query);
  if (isNaN(lim) || lim <= 0 || lim > 50) lim = 15;

  // 1. Consultar memoria de alertas de los últimos 6 minutos (The Dude + Zabbix 20 + Zabbix 35)
  let recentAlerts = [];
  try {
    const memRes = await this.helpers.httpRequest({
      method: 'GET',
      url: 'http://host.docker.internal:11440/alerts/recent?minutes=6',
      json: true
    });
    if (memRes && memRes.alerts) {
      recentAlerts = memRes.alerts;
    }
  } catch (e) {}

  // 2. Consultar problemas activos en Zabbix 35
  let zabbixProblems = [];
  try {
    const res = await this.helpers.httpRequest({
      method: 'POST',
      url: 'http://192.168.1.100/zabbix/api_jsonrpc.php',
      headers: {
        'Authorization': 'Bearer YOUR_ZABBIX_API_TOKEN',
        'Content-Type': 'application/json'
      },
      body: {
        jsonrpc: '2.0',
        method: 'problem.get',
        params: {
          output: ['eventid', 'name', 'severity', 'clock', 'objectid'],
          sortfield: ['eventid'],
          sortorder: 'DESC',
          limit: lim
        },
        id: 1
      },
      json: true
    });

    if (res && res.result && res.result.length > 0) {
      const triggerIds = res.result.map(p => p.objectid).filter(id => id && id !== '0');
      let hostMap = {};

      if (triggerIds.length > 0) {
        try {
          const trigRes = await this.helpers.httpRequest({
            method: 'POST',
            url: 'http://192.168.1.100/zabbix/api_jsonrpc.php',
            headers: {
              'Authorization': 'Bearer YOUR_ZABBIX_API_TOKEN',
              'Content-Type': 'application/json'
            },
            body: {
              jsonrpc: '2.0',
              method: 'trigger.get',
              params: {
                output: ['triggerid'],
                selectHosts: ['hostid', 'host', 'name'],
                triggerids: triggerIds
              },
              id: 2
            },
            json: true
          });
          if (trigRes && trigRes.result) {
            trigRes.result.forEach(t => {
              if (t.hosts && t.hosts[0]) {
                hostMap[t.triggerid] = t.hosts[0].name || t.hosts[0].host;
              }
            });
          }
        } catch (e) {}
      }

      const sevMap = { '0': 'No clasificado', '1': 'Información', '2': 'Advertencia', '3': 'Promedio', '4': 'Alta', '5': 'Desastre' };
      zabbixProblems = res.result.slice(0, lim).map(p => ({
        origen: 'Zabbix35',
        equipo: hostMap[p.objectid] || 'Equipo de Red',
        problema: p.name,
        severidad: sevMap[p.severity] || p.severity,
        hora: new Date(parseInt(p.clock) * 1000).toLocaleTimeString('es-ES', { hour: '2-digit', minute: '2-digit' })
      }));
    }
  } catch (e) {}

  if (recentAlerts.length === 0 && zabbixProblems.length === 0) {
    return 'No hay problemas activos ni alertas registradas en los últimos 6 minutos. Toda la red opera con normalidad.';
  }

  return JSON.stringify({
    alertas_recientes_ultimos_6_min: recentAlerts.map(a => ({
      origen: a.source,
      equipo: a.host,
      problema: a.problem,
      severidad: a.severity,
      estado: a.status,
      hora_evento: a.hora,
      hace_segundos: a.hace_segundos
    })),
    problemas_activos_zabbix: zabbixProblems
  });
} catch (err) {
  return 'Error al consultar alertas: ' + err.message;
}

