  });

  if (!res || !res.result || res.result.length === 0) {
    return 'No se registran eventos previos en el historial de Zabbix.';
  }

  const sevMap = { '0': 'No clasificado', '1': 'Info', '2': 'Advertencia', '3': 'Promedio', '4': 'Alta', '5': 'Desastre' };
  return JSON.stringify(res.result.slice(0, lim).map(e => ({
    equipo: (e.hosts && e.hosts[0]) ? (e.hosts[0].name || e.hosts[0].host) : 'Desconocido',
    evento: e.name,
    estado: e.value === '1' ? 'GENERADO (Problema)' : 'RECUPERADO (OK)',
    severidad: sevMap[e.severity] || e.severity,
    hora: new Date(parseInt(e.clock) * 1000).toLocaleTimeString('es-ES', { hour: '2-digit', minute: '2-digit' })
  })));
} catch (err) {
  return 'Error al consultar historial en Zabbix: ' + err.message;
}

try {
  const buscaTermino = (typeof query !== 'undefined' && query) ? String(query).trim() : ((typeof input !== 'undefined' && input) ? String(input).trim() : '');

  if (!buscaTermino) {
    return 'Por favor, proporciona un nombre o una IP para realizar la búsqueda.';
  }

  const esIP = /^(?:[0-9]{1,3}\.){3}[0-9]{1,3}$/.test(buscaTermino);
  let hostsFound = [];

  if (esIP) {
    const ifaceRes = await this.helpers.httpRequest({
      method: 'POST',
      url: 'http://192.168.1.100/zabbix/api_jsonrpc.php',
      headers: {
        'Authorization': 'Bearer YOUR_ZABBIX_API_TOKEN',
        'Content-Type': 'application/json'
      },
      body: {
        jsonrpc: '2.0',
        method: 'hostinterface.get',
        params: {
          output: ['hostid', 'ip', 'port'],
          filter: { ip: buscaTermino }
        },
        id: 1
      },
      json: true
    });

    const hostIds = ifaceRes?.result?.map(i => i.hostid) || [];
    if (hostIds.length > 0) {
      const hostRes = await this.helpers.httpRequest({
        method: 'POST',
        url: 'http://192.168.1.100/zabbix/api_jsonrpc.php',
        headers: {
          'Authorization': 'Bearer YOUR_ZABBIX_API_TOKEN',
          'Content-Type': 'application/json'
        },
        body: {
          jsonrpc: '2.0',
          method: 'host.get',
          params: {
            output: ['hostid', 'host', 'name', 'status', 'available'],
            selectInterfaces: ['ip'],
            selectGroups: ['name'],
            hostids: hostIds
          },
          id: 2
        },
        json: true
      });
      hostsFound = hostRes?.result || [];
    }
  } else {
    const hostRes = await this.helpers.httpRequest({
      method: 'POST',
      url: 'http://192.168.1.100/zabbix/api_jsonrpc.php',
      headers: {
        'Authorization': 'Bearer YOUR_ZABBIX_API_TOKEN',
        'Content-Type': 'application/json'
      },
      body: {
        jsonrpc: '2.0',
        method: 'host.get',
        params: {
          output: ['hostid', 'host', 'name', 'status', 'available'],
          selectInterfaces: ['ip'],
          selectGroups: ['name'],
          search: { name: buscaTermino },
          searchByAny: true,
          limit: 15
        },
        id: 1
      },
      json: true
    });
    hostsFound = hostRes?.result || [];
  }

  if (!hostsFound || hostsFound.length === 0) {
    return `ERROR_NOC: El equipo o IP '${buscaTermino}' no está registrado en la base de datos de Zabbix. Informa al usuario exactamente que no se encontró ningún registro para este criterio.`;
  }

  return JSON.stringify(hostsFound.map(h => ({
    nombre: h.name || h.host,
    ip: h.interfaces?.[0]?.ip || 'Sin IP',
    estado: h.status === '0' ? (h.available === '1' ? 'OK (Online)' : (h.available === '2' ? 'FALLA (Offline)' : 'Monitoreado')) : 'Deshabilitado',
    grupos: h.groups?.map(g => g.name).slice(0, 2).join(', ')
  })));
} catch (err) {
  return 'Error al buscar equipo en Zabbix: ' + err.message;
}

