try {
  const buscaTermino = (typeof query !== 'undefined' && query) ? String(query).trim() : ((typeof input !== 'undefined' && input) ? String(input).trim() : '');
  if (!buscaTermino) return 'Proporciona una IP o nombre de equipo para hacer ping.';

  const esIP = /^(?:[0-9]{1,3}\.){3}[0-9]{1,3}$/.test(buscaTermino);
  let hostIdTarget = null;
  let hostNameZabbix = null;

  // 1. Intentar encontrar el equipo en Zabbix
  if (esIP) {
    const ifaceRes = await this.helpers.httpRequest({
      method: 'POST', url: 'http://192.168.1.100/zabbix/api_jsonrpc.php',
      headers: { 'Authorization': 'Bearer YOUR_ZABBIX_API_TOKEN', 'Content-Type': 'application/json' },
      body: { jsonrpc: '2.0', method: 'hostinterface.get', params: { output: ['hostid'], filter: { ip: buscaTermino } }, id: 1 }, json: true
    });
    if (ifaceRes?.result?.length > 0) hostIdTarget = ifaceRes.result[0].hostid;
  }

  if (!hostIdTarget) {
    const hostRes = await this.helpers.httpRequest({
      method: 'POST', url: 'http://192.168.1.100/zabbix/api_jsonrpc.php',
      headers: { 'Authorization': 'Bearer YOUR_ZABBIX_API_TOKEN', 'Content-Type': 'application/json' },
      body: { jsonrpc: '2.0', method: 'host.get', params: { output: ['hostid', 'name'], search: { name: buscaTermino }, searchByAny: true, limit: 1 }, id: 1 }, json: true
    });
    if (hostRes?.result?.length > 0) {
      hostIdTarget = hostRes.result[0].hostid;
      hostNameZabbix = hostRes.result[0].name;
    }
  }

  // 2a. Si está en Zabbix: usar script nativo de Zabbix
  if (hostIdTarget) {
    const pingRes = await this.helpers.httpRequest({
      method: 'POST', url: 'http://192.168.1.100/zabbix/api_jsonrpc.php',
      headers: { 'Authorization': 'Bearer YOUR_ZABBIX_API_TOKEN', 'Content-Type': 'application/json' },
      body: { jsonrpc: '2.0', method: 'script.execute', params: { scriptid: '1', hostid: hostIdTarget }, id: 2 }, json: true
    });
    const nombre = hostNameZabbix || buscaTermino;
    if (pingRes?.result?.response === 'success') {
      return JSON.stringify({ objetivo: nombre, en_zabbix: 'Sí', resultado: pingRes.result.value, estado: 'RESPONDE' });
    }
    // Si Zabbix falla, continúa al fallback
  }

  // 2b. Fallback: ping nativo Linux desde el servidor (para IPs no en Zabbix)
  const target = esIP ? buscaTermino : buscaTermino;
  const nativeRes = await this.helpers.httpRequest({
    method: 'GET',
    url: `http://host.docker.internal:11440/ping?target=${encodeURIComponent(target)}`,
    json: true
  });

  const inZabbix = hostIdTarget ? 'registrado en Zabbix' : 'NO registrado en Zabbix';

  if (nativeRes.error && !nativeRes.alive) {
    return `Ping a ${target} (${inZabbix}):\nERROR: ${nativeRes.error}`;
  }

  const alive = nativeRes.alive;
  const estado = alive ? 'RESPONDE (Online)' : 'NO RESPONDE (Offline/Caído)';
  const loss = nativeRes.packet_loss_pct ?? 100;
  const avg = nativeRes.rtt_avg_ms ? `${nativeRes.rtt_avg_ms} ms` : 'N/D';
  const minR = nativeRes.rtt_min_ms ? `${nativeRes.rtt_min_ms} ms` : 'N/D';
  const maxR = nativeRes.rtt_max_ms ? `${nativeRes.rtt_max_ms} ms` : 'N/D';

  return JSON.stringify({
    objetivo: target,
    en_zabbix: hostIdTarget ? 'Sí' : 'No',
    estado: estado,
    paquetes_enviados: nativeRes.packets_sent || 4,
    paquetes_recibidos: nativeRes.packets_received || 0,
    perdida_pct: `${loss}%`,
    latencia_min: minR,
    latencia_promedio: avg,
    latencia_max: maxR
  });
} catch (err) {
  return 'Error al ejecutar ping: ' + err.message;
}

try {
  const buscaTermino = (typeof query !== 'undefined' && query) ? String(query).trim() : ((typeof input !== 'undefined' && input) ? String(input).trim() : '');
  if (!buscaTermino) return 'Proporciona una IP o nombre de equipo para consultar su tráfico.';

  const esIP = /^(?:[0-9]{1,3}\.){3}[0-9]{1,3}$/.test(buscaTermino);
  let hostIdTarget = null;
  let hostName = buscaTermino;

  if (esIP) {
    const ifaceRes = await this.helpers.httpRequest({
      method: 'POST', url: 'http://192.168.1.100/zabbix/api_jsonrpc.php',
      headers: { 'Authorization': 'Bearer YOUR_ZABBIX_API_TOKEN', 'Content-Type': 'application/json' },
      body: { jsonrpc: '2.0', method: 'hostinterface.get', params: { output: ['hostid'], filter: { ip: buscaTermino } }, id: 1 }, json: true
    });
    if (ifaceRes?.result?.length > 0) hostIdTarget = ifaceRes.result[0].hostid;
  }

  if (!hostIdTarget) {
    const hostRes = await this.helpers.httpRequest({
      method: 'POST', url: 'http://192.168.1.100/zabbix/api_jsonrpc.php',
      headers: { 'Authorization': 'Bearer YOUR_ZABBIX_API_TOKEN', 'Content-Type': 'application/json' },
      body: { jsonrpc: '2.0', method: 'host.get', params: { output: ['hostid', 'name'], search: { name: buscaTermino }, searchByAny: true, limit: 1 }, id: 1 }, json: true
    });
    if (hostRes?.result?.length > 0) {
      hostIdTarget = hostRes.result[0].hostid;
      hostName = hostRes.result[0].name;
    }
  }

  if (!hostIdTarget) return `ERROR_NOC: El equipo o IP '${buscaTermino}' no existe en Zabbix.`;

  const itemsRes = await this.helpers.httpRequest({
    method: 'POST', url: 'http://192.168.1.100/zabbix/api_jsonrpc.php',
    headers: { 'Authorization': 'Bearer YOUR_ZABBIX_API_TOKEN', 'Content-Type': 'application/json' },
    body: { jsonrpc: '2.0', method: 'item.get', params: { hostids: [hostIdTarget], output: ['name', 'key_', 'lastvalue'], search: { key_: 'net.if' }, limit: 20 }, id: 2 }, json: true
  });

  const items = itemsRes?.result || [];
  if (items.length === 0) return `El equipo '${hostName}' no tiene interfaces de tráfico SNMP registradas en Zabbix.`;

  const resultLines = items.map(it => {
    const valMbps = (parseFloat(it.lastvalue || 0) / 1000000.0).toFixed(2);
    return { interfaz: it.name, velocidad: `${valMbps} Mbps` };
  });

  return JSON.stringify({
    equipo: hostName,
    consumo_actual: resultLines.slice(0, 8),
    nota: "Si deseas ver la gráfica visual en imagen, escribe: /trafico " + buscaTermino
  });
} catch (err) {
  return 'Error al consultar tráfico en Zabbix: ' + err.message;
}

