try {
  let target = '';
  let action = 'status';
  let rawInput = (typeof input !== 'undefined' && input) ? String(input).trim() : ((typeof query !== 'undefined' && query) ? String(query).trim() : '');

  if (rawInput.startsWith('{') && rawInput.endsWith('}')) {
    try {
      const parsedObj = JSON.parse(rawInput);
      target = String(parsedObj.target || parsedObj.vm_id || parsedObj.vmid || parsedObj.id || parsedObj.vm || parsedObj.host || '').trim();
      action = String(parsedObj.action || parsedObj.accion || action).trim();
    } catch (e) {}
  }

  if (!target && rawInput) {
    const idMatch = rawInput.match(/(?:vm_?id|id|vm)?\s*[:=]?\s*(\d+)/i);
    if (idMatch) {
      target = idMatch[1];
    } else {
      const words = rawInput.replace(/[{}\"\':,]/g, ' ').trim().split(/\s+/);
      const acts = ['start', 'levantar', 'encender', 'iniciar', 'stop', 'parar', 'apagar', 'detener', 'reboot', 'reiniciar', 'reset', 'pause', 'pausar', 'hibernate', 'hibernar', 'resume', 'reanudar', 'migrate', 'migrar', 'clone', 'clonar', 'console', 'consola', 'status', 'estado', 'info', 'detalles', 'consultar', 'ver'];
      for (const w of words) {
        if (acts.includes(w.toLowerCase())) action = w.toLowerCase();
        else if (!target && !['action', 'vm', 'vmid', 'id', 'vm_id'].includes(w.toLowerCase())) target = w;
      }
      if (!target && words.length > 0) target = words[0];
    }
  }

  if (!target) return JSON.stringify({ ok: false, error: 'Indica el nombre o VMID de la máquina virtual.' });

  const targetUrl = 'http://host.docker.internal:11440/proxmox/vm-action';
  const res = await this.helpers.httpRequest({
    method: 'POST',
    url: targetUrl,
    body: {
      target: target,
      action: action,
      phase: 'check'
    },
    json: true
  });

  return JSON.stringify(res);
} catch (err) {
  return JSON.stringify({ ok: false, error: 'Error al consultar VM en Proxmox: ' + err.message });
}

