        action = p.toLowerCase();
      } else if (!target) {
        target = p;
      }
    }
    if (!target) target = parts[0];
  }

  if (!target) return JSON.stringify({ ok: false, error: 'Indica el nombre o VMID de la máquina virtual a ejecutar.' });

  const targetUrl = 'http://host.docker.internal:11440/proxmox/vm-action';
  const res = await this.helpers.httpRequest({
    method: 'POST',
    url: targetUrl,
    body: {
      target: target,
      action: action,
      phase: 'execute'
    },
    json: true
  });

  return JSON.stringify(res);
} catch (err) {
  return JSON.stringify({ ok: false, error: 'Error al ejecutar acción en Proxmox: ' + err.message });
}
